class Component extends DCLogic {
  componentDidMount() {
    // Responsive tweaks that inline styles + media queries can't express here:
    const applyResponsive = () => {
      const wide = window.innerWidth > 900;
      const links = this.base && this.base.querySelector ? this.base.querySelector('.od-navlinks') : document.querySelector('.od-navlinks');
      if (links) links.style.display = wide ? 'flex' : 'none';
      document.querySelectorAll('.od-2col').forEach(el => { el.style.gridTemplateColumns = wide ? el.getAttribute('data-cols') || '1fr 1fr' : '1fr'; });
      document.querySelectorAll('.od-3col').forEach(el => { el.style.gridTemplateColumns = wide ? 'repeat(3,1fr)' : '1fr'; });
      document.querySelectorAll('.od-swatch4').forEach(el => { el.style.gridTemplateColumns = wide ? 'repeat(4,1fr)' : 'repeat(2,1fr)'; });
      document.querySelectorAll('.od-tblock').forEach(el => { el.style.gridTemplateColumns = wide ? (el.style.gridTemplateColumns.includes('4') ? 'repeat(4,1fr)' : 'repeat(3,1fr)') : 'repeat(2,1fr)'; });
      document.querySelectorAll('.od-arc').forEach(el => { el.style.gridTemplateColumns = wide ? 'repeat(3,1fr)' : '1fr'; });
    };
    applyResponsive();
    this._onResize = applyResponsive;
    window.addEventListener('resize', applyResponsive);
  }
  componentWillUnmount() {
    if (this._onResize) window.removeEventListener('resize', this._onResize);
  }
  renderVals() { return {}; }
}

